void NativeWhipSsh::registerModule(
    jsi::Runtime &rt, std::shared_ptr<react::CallInvoker> callInvoker) {
  auto invoker =
      std::make_shared<uniffi_runtime::UniffiCallInvoker>(callInvoker);
  auto tm = std::make_shared<NativeWhipSsh>(rt, invoker);
  auto obj = rt.global().createFromHostObject(rt, tm);
  rt.global().setProperty(rt, "NativeWhipSsh", obj);
}

void NativeWhipSsh::unregisterModule(jsi::Runtime &rt) {
  uniffi::whip_ssh::registry::clearRegistry();
}

jsi::Value NativeWhipSsh::get(jsi::Runtime &rt, const jsi::PropNameID &name) {
  try {
    return jsi::Value(rt, props.at(name.utf8(rt)));
  } catch (std::out_of_range &) {
    return jsi::Value::undefined();
  }
}

std::vector<jsi::PropNameID> NativeWhipSsh::getPropertyNames(jsi::Runtime &rt) {
  std::vector<jsi::PropNameID> rval;
  for (auto &[key, value] : props) {
    rval.push_back(jsi::PropNameID::forUtf8(rt, key));
  }
  return rval;
}

void NativeWhipSsh::set(jsi::Runtime &rt, const jsi::PropNameID &name,
                        const jsi::Value &value) {
  props.insert_or_assign(name.utf8(rt), &value);
}

